#!/usr/bin/env bash
set -Eeuo pipefail
source "$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)/deploy_info.sh"
backup_all(){ ensure_dirs; local ts archive items=() i; ts="$(date '+%Y%m%d_%H%M%S')"; archive="$BACKUP_DIR/astrbot_backup_${ts}.tar.gz"; step "Creating backup ${archive}"; for i in data napcat snowluma .env napcat_index.tsv protocols.json ports.json deploy_info.txt; do [[ -e "$INSTALL_PREFIX/$i" ]] && items+=("$i"); done; tar -czf "$archive" --exclude='Singleton*' --exclude='snowluma/*/qq-data/*/Cache' --exclude='*.sock' -C "$INSTALL_PREFIX" "${items[@]}"; chmod 600 "$archive" || true; success "Backup completed: $archive"; }
restore_backup(){ local archive="${1:-}"; [[ -n "$archive" ]] || { ls -1t "$BACKUP_DIR"/*.tar.gz 2>/dev/null | head -n 10; read -r -p $'\u8bf7\u8f93\u5165\u8981\u6062\u590d\u7684\u5907\u4efd\u6587\u4ef6\uff1a' archive; }; [[ -f "$archive" ]] || { fail "Backup file not found: $archive"; return 1; }; step "Stopping containers and restoring backup"; stop_all || true; tar -xzf "$archive" -C "$INSTALL_PREFIX"; success "Restore completed; starting containers"; start_all; }
